commands.code:
mkdir -p ~/dev-opps-lab/platform24/{infra,config,evidence}
cd ~/dev-opps-lab/platform24/infra
export AWS_PROFILE=devopps-provisioner AWS_REGION=us-east-1 AWS_PAGER=""
aws sso login --profile "$AWS_PROFILE"
aws sts get-caller-identity
read -r -p "Recorded week-18 backend bucket: " STATE_BUCKET
read -r -p "Your current public IPv4 address (without /32): " ADMIN_IP
export STATE_BUCKET ADMIN_IP
if [ ! -f "$HOME/.ssh/devopps24" ]; then ssh-keygen -t ed25519 -f "$HOME/.ssh/devopps24" -C devopps24; fi
cat > main.tf <<'EOF'
terraform {
  required_version = ">= 1.10, < 2.0"
  required_providers { aws = { source = "hashicorp/aws", version = "~> 6.0" } }
  backend "s3" {}
}
provider "aws" { region = "us-east-1" }
variable "admin_cidr" {
  type = string
  validation {
    condition = can(cidrhost(var.admin_cidr, 0)) && can(regex("^[0-9.]+/32$", var.admin_cidr))
    error_message = "Use your verified administrator IPv4 /32 only."
  }
}
variable "ssh_public_key" { type = string }
data "aws_ssm_parameter" "ubuntu" {
  name = "/aws/service/canonical/ubuntu/server/24.04/stable/current/amd64/hvm/ebs-gp3/ami-id"
}
resource "aws_vpc" "lab" {
  cidr_block = "10.78.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = { Name = "devopps24", Course = "DevOpps" }
}
resource "aws_subnet" "lab" {
  vpc_id = aws_vpc.lab.id
  cidr_block = "10.78.1.0/24"
  tags = { Name = "devopps24" }
}
resource "aws_internet_gateway" "lab" { vpc_id = aws_vpc.lab.id }
resource "aws_route_table" "lab" { vpc_id = aws_vpc.lab.id }
resource "aws_route" "internet" {
  route_table_id = aws_route_table.lab.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.lab.id
}
resource "aws_route_table_association" "lab" {
  subnet_id = aws_subnet.lab.id
  route_table_id = aws_route_table.lab.id
}
resource "aws_security_group" "lab" {
  name_prefix = "devopps24-"
  vpc_id = aws_vpc.lab.id
}
resource "aws_vpc_security_group_ingress_rule" "ssh" {
  security_group_id = aws_security_group.lab.id
  cidr_ipv4 = var.admin_cidr
  ip_protocol = "tcp"
  from_port = 22
  to_port = 22
}
resource "aws_vpc_security_group_egress_rule" "outbound" {
  security_group_id = aws_security_group.lab.id
  cidr_ipv4 = "0.0.0.0/0"
  ip_protocol = "-1"
}
resource "aws_key_pair" "lab" {
  key_name_prefix = "devopps24-"
  public_key = var.ssh_public_key
}
resource "aws_instance" "app" {
  ami = nonsensitive(data.aws_ssm_parameter.ubuntu.value)
  instance_type = "t3.small"
  subnet_id = aws_subnet.lab.id
  associate_public_ip_address = true
  vpc_security_group_ids = [aws_security_group.lab.id]
  key_name = aws_key_pair.lab.key_name
  metadata_options { http_tokens = "required" }
  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted = true
    delete_on_termination = true
  }
  tags = { Name = "devopps24", Course = "DevOpps" }
  depends_on = [aws_route.internet]
}
output "public_ip" { value = aws_instance.app.public_ip }
output "instance_id" { value = aws_instance.app.id }
EOF
python3 - <<'PY'
import json,os,ipaddress
from pathlib import Path
ip=ipaddress.IPv4Address(os.environ['ADMIN_IP'])
Path('lab.auto.tfvars.json').write_text(json.dumps({'admin_cidr':str(ip)+'/32','ssh_public_key':(Path.home()/'.ssh/devopps24.pub').read_text()}))
PY
terraform init -backend-config="bucket=$STATE_BUCKET" -backend-config="key=vm24/terraform.tfstate" -backend-config="region=us-east-1" -backend-config="encrypt=true" -backend-config="use_lockfile=true"
terraform fmt
terraform validate
terraform plan -out=create.tfplan
terraform show -no-color create.tfplan
